"""One fresh unaccepted literal RGB diagnostic bake onto unchanged authored UVs."""
import argparse,hashlib,json,shutil,subprocess,sys
from io import BytesIO
from pathlib import Path
import numpy as np
from PIL import Image
import target_contract as contract
from place_purposebuilt_pelvis import read_glb,raw_corners,embedded_maps
import skin_lighting_atlas as atlas
import orthographic_reference_projection as cameras
import reference_color_reprojection as color

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
def pin(p):p=Path(p).resolve();return {'path':str(p),'sha256':sha(p),'byteCount':p.stat().st_size}
def checked(row):p=Path(row['path']).resolve();contract.require(sha(p)==row['sha256'],'Frozen projection input changed: '+str(p));return p

def main():
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--config',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);parser.add_argument('--toolchain',type=Path,required=True);parser.add_argument('--migration-receipt',type=Path,required=True);args=parser.parse_args()
 cfg=json.loads(args.config.read_text());contract.require(set(cfg)=={'schemaVersion','kind','diagnosticOnly','part','studyReceipt','generationReceipt','targetContract','depthToleranceSourceUnits','minimumGeometricIncidence','alphaErosionPixels','crossViewDifferenceShadeBytes'},'Explicit known diagnostic controls required')
 contract.require(cfg['schemaVersion']==1 and cfg['kind']=='literal-reference-rgb-diagnostic' and cfg['diagnosticOnly'] is True,'Unaccepted diagnostic required')
 study_path=checked(cfg['studyReceipt']);study=json.loads(study_path.read_text());part=[p for p in study['parts'] if p['part']==cfg['part']];contract.require(len(part)==1,'Unique studied source part required');part=part[0]
 target_path=checked(cfg['targetContract']);target=contract.load(target_path);contract.require(target['id']==study['targetId'] and sha(target_path)==part['targetContract']['sha256'],'Cross-target projection rejected')
 generation_path=checked(cfg['generationReceipt']);generation=json.loads(generation_path.read_text());source=checked(part['model']);contract.require(generation.get('state')=='success' and any(Path(x['localPath']).resolve()==source and x['sha256']==sha(source) for x in generation['outputs']),'Source generation binding rejected')
 out=args.output.resolve();contract.require(not out.exists(),'Fresh diagnostic output required');out.mkdir();(out/'helpers').mkdir();frozen={str(study_path):sha(study_path),str(target_path):sha(target_path),str(source):sha(source),str(generation_path):sha(generation_path),str(args.config.resolve()):sha(args.config)}
 for f,h in study['frozenInputs'].items():contract.require(sha(f)==h,'Studied input changed');frozen[f]=h
 for f in (Path(__file__).resolve(),Path(color.__file__).resolve(),Path(atlas.__file__).resolve(),Path(cameras.__file__).resolve(),args.toolchain.resolve(),args.migration_receipt.resolve()):frozen[str(f)]=sha(f);shutil.copyfile(f,out/'helpers'/f.name)
 doc,binary=read_glb(source);extra={};p,n,uv,primitives=raw_corners(doc,binary,extra=extra);originalimages=[];allmaps=embedded_maps(doc,binary)
 for material in {r['material'] for r in primitives}:
  row=doc['materials'][material]['pbrMetallicRoughness'];contract.require(row.get('baseColorFactor',[1]*4)==[1]*4 and row['baseColorTexture'].get('texCoord',0)==0,'Literal original base-color policy requires white factor/UV0')
  imageindex=doc['textures'][row['baseColorTexture']['index']]['source'];view=doc['bufferViews'][doc['images'][imageindex]['bufferView']];start=view.get('byteOffset',0);blob=binary[start:start+view['byteLength']];originalimages.append(blob)
 contract.require(len(set(originalimages))==1,'One common immutable color atlas required for this diagnostic');original=np.asarray(Image.open(BytesIO(originalimages[0])).convert('RGB'));contract.require(original.shape==(2048,2048,3),'Original2K atlas required');(out/'original-basecolor-encoded.png').write_bytes(originalimages[0]);Image.fromarray(original).save(out/'original-basecolor.png')
 np.savez_compressed(out/'exact-source-corners.npz',positions=p,normals=n,uv=uv,**{k:np.asarray(v['rows']).reshape(-1,3,v['rows'][0].shape[-1]) for k,v in extra.items()})
 print('Diagnostic barycentric UV coverage; no skin/cloth ownership inferred',flush=True);mask=atlas.geometry_masks(p,n,uv,['skin']*len(p),2048,[],guard=2)
 views={};camera_records=[]
 for row in part['views']:
  name=row['view'];rgbpath=checked(row['referenceRgb']);alphapath=checked(row['referenceAlpha']);depthpath=checked(row['surface']);rgb=np.asarray(Image.open(rgbpath).convert('RGB'));alpha=np.asarray(Image.open(alphapath).convert('RGBA'))[:,:,3]>8;depth=np.load(depthpath,allow_pickle=False)['depth'];views[name]={'rgb':rgb,'alpha':alpha,'depth':depth};camera_records.append({**row,'registrationAccepted':False,'garmentBoundariesAccepted':False})
 print('Project exact approved visible cardinal RGB, excluding unresolved samples',flush=True);derived,fields=color.project_rgb(p,mask,original,views,part['declaredSharedOrthoSpan'],cfg['depthToleranceSourceUnits'],cfg['minimumGeometricIncidence'],cfg['alphaErosionPixels'],cfg['crossViewDifferenceShadeBytes']/255)
 Image.fromarray(derived).save(out/'derived-reference-basecolor.png');Image.fromarray(fields['confidence']*255).convert('L').save(out/'confidence.png');Image.fromarray(fields['accepted'].astype('u1')*255).save(out/'accepted.png');Image.fromarray(fields['crossViewColorConflict'].astype('u1')*255).save(out/'cross-view-conflict.png')
 np.savez_compressed(out/'projection-lineage.npz',**fields,uvCoverage=mask['coverage'],uvAmbiguous=mask['ambiguous'],uvProtected=mask['protected'],sourceFace=mask['ownerFace'],sourceBarycentricPosition=mask['positionLocal'],sourceAuthoredUnitNormal=mask['authoredUnitNormal'])
 worker=Path(__file__).with_name('blender_reference_color_preview.py');launcher=Path(__file__).with_name('launch_shared_tool.py')
 for f in (worker,launcher):frozen[str(f.resolve())]=sha(f)
 job={'kind':'reference-color-diagnostic-preview','diagnosticOnly':True,'span':part['declaredSharedOrthoSpan'],'arrays':pin(out/'exact-source-corners.npz'),'images':{'original':pin(out/'original-basecolor.png'),'projected':pin(out/'derived-reference-basecolor.png')},'frozenInputs':frozen};save(out/'preview-input.json',job)
 subprocess.run([sys.executable,'-B',str(launcher),'--toolchain',str(args.toolchain.resolve()),'--migration-receipt',str(args.migration_receipt.resolve()),'--tool','blender','--output',str(out/'preview-launch'),'--','--python',str(worker),'--','--input',str(out/'preview-input.json'),'--output',str(out/'preview')],check=True)
 for f,h in frozen.items():contract.require(sha(f)==h,'Original/frozen projection source changed')
 delta=np.max(abs(derived.astype(int)-original.astype(int)),axis=2);coverage=mask['coverage'];result={'schemaVersion':1,'kind':'literal-reference-rgb-diagnostic-receipt','targetContract':str(target_path),'targetContractSha256':sha(target_path),'targetId':target['id'],'rigRevision':target['rig']['revision'],'coordinateSpace':'generator-source','part':cfg['part'],'diagnosticOnly':True,'configuration':pin(args.config.resolve()),'source':pin(source),'sourceBinarySha256':hashlib.sha256(binary).hexdigest(),'generationReceipt':pin(generation_path),'studyReceipt':pin(study_path),'referenceSource':part['sourceReference'],'referenceNormalization':part['normalization'],'originalEmbeddedMaps':allmaps,'originalGeometryUvsNormalsTangentsSignsIndicesMapsChanged':False,'originalNormalAndOrmPixelsChanged':False,'derivedRgb':pin(out/'derived-reference-basecolor.png'),'projectionLineage':pin(out/'projection-lineage.npz'),'sourceCornerArrays':pin(out/'exact-source-corners.npz'),'cameraRecords':camera_records,'sharedOrthoSpan':part['declaredSharedOrthoSpan'],'cameraCenter':[0,0,0],'registrationTransform':'Identity; no uniform/nonuniform/image warp performed','registrationAccepted':False,'samplingPolicy':'Original rawGLTF top-left UV texel centers; references bilinear in linear RGB; weighted linear color blend of agreeing eligible views; encodedsRGB output; no background extrapolation','sourceViewOrder':list(views),'controls':{k:cfg[k] for k in ('depthToleranceSourceUnits','minimumGeometricIncidence','alphaErosionPixels','crossViewDifferenceShadeBytes')},'coveragePixels':int(coverage.sum()),'ambiguousUvPixels':int(mask['ambiguous'].sum()),'eligibleUvPixels':int(fields['projectionEligibleUV'].sum()),'acceptedProjectionPixels':int(fields['accepted'].sum()),'conflictingViewPixels':int(fields['crossViewColorConflict'].sum()),'coveredUnsampledPixels':int((coverage&~fields['accepted']).sum()),'changedPixelCount':int(np.count_nonzero(delta)),'changedOutsideAccepted':int(np.count_nonzero(delta[~fields['accepted']])),'maximumColorShadeDifference':int(delta.max()),'materialRoleClassification':'Unclassified diagnosticRGB only; no skin/cloth votes or garment ownership approved','paddingApplied':False,'aoOrLightingMultiplied':False,'previewReceipt':pin(out/'preview/preview.json'),'previewLaunch':pin(out/'preview-launch/launch.json'),'frozenInputs':frozen,'garmentBoundariesAccepted':False,'anatomyAccepted':False,'selected':False,'nativeCompiled':False,'clientAccepted':False,'limits':['Identity camera registration has recorded contour/landmark errors; projected garment edges may inherit them. No perview warp or recolor mask applied.','Fourcardinal source visibility leaves caps/undersides/grazing/occluded/conflicting/ambiguous surfaces at literal original paint. Unsampled original paint may include rejected extra straps.','Colorconflict48bytes is diagnostic threshold, not approved skin/cloth semantic consistency. Material ownership remains an independent review gate.','Projection can replace visible paint and preserve authored baked shadow; cannot remove physical straps/ridges or originalnormalmap relief.','Existing original2K maps/GLB are untouched; sidecarRGB/emission previews do not establish PLT/palette/engine filtering/native/client acceptance.']};save(out/'projection.json',result);print(json.dumps({'receipt':str(out/'projection.json'),'sha256':sha(out/'projection.json'),'coverage':result['coveragePixels'],'projected':result['acceptedProjectionPixels'],'conflicting':result['conflictingViewPixels'],'selected':False}),flush=True)
if __name__=='__main__':main()

